/**
 * 🎨 PHOTO REFERENCE SHAPE DATA
 * 36533 points extracted from reference photo
 * [x, y, r, g, b] per point
 */
(function() {
  window.PHOTO_SHAPE_BASE64 = "";
  window.PHOTO_SHAPE_POINT_COUNT = 36533;

  window.getPhotoShapePoints = function() {
    if (window._cachedPhotoPoints) return window._cachedPhotoPoints;
    const binaryStr = atob(window.PHOTO_SHAPE_BASE64);
    const bytes = new Uint8Array(binaryStr.length);
    for (let i = 0; i < binaryStr.length; i++) {
      bytes[i] = binaryStr.charCodeAt(i);
    }
    window._cachedPhotoPoints = new Float32Array(bytes.buffer);
    return window._cachedPhotoPoints;
  };
})();
